pattern_library.example:
// Async/await: interleaved execution
stack(
  sound("bd*2").gain(0.7),
  sound("hh*4").early(0.25).gain(0.56),
  sound("sd*2").early(0.5).gain(0.42)
)

// Network protocol: request/response
stack(
  sound("rim").struct("t ~ t ~").gain(0.7),
  sound("oh").struct("~ t ~ t").late(0.25).gain(0.6)
).every(4, x => x.fast(1.5))

// Event loop: repeating cycles
stack(
  sound("bd*4"),
  sound("clap").euclid(5, 8),
  note("c3 e3 g3 c4").sound("square").fast(2)
).every(4, x => x.jux(rev))

// Message queue: sequential processing
stack(
  sound("9000_perc").struct("t ~ t ~ t ~ ~ t").gain(0.8),
  sound("clap").late(0.125).gain(0.7),
  sound("9000_bd*4").lpf(400)
)

// Cache: hits (frequent) and misses (sparse)
stack(
  sound("hh*8").gain(0.5),
  sound("9000_perc").struct("~ ~ t ~ ~ ~ t ~").gain(0.9).speed(0.8)
).every(16, x => x.rev())

// Garbage collection: periodic cleanup
stack(
  note("c3 d3 e3 f3 g3 a3 b3 c4").sound("gm_piano").fast(2),
  sound("z_noise").struct("~ ~ ~ ~ ~ ~ ~ t").gain(0.7)
).every(8, x => x.slow(4).gain(0.3))
